// Generated by AI
using UnityEngine;

public class AccessibilityManager : MonoBehaviour
{
    [Header("HUD Contrast")]
    [SerializeField] private GameObject hudNormal;
    [SerializeField] private GameObject hudHigh;
    [SerializeField] private GameObject hudVeryHigh;

    [Header("Contrast Selection")]
    [SerializeField] private GameObject contrastNormalGreen;
    [SerializeField] private GameObject contrastHighGreen;
    [SerializeField] private GameObject contrastVeryHighGreen;

    [Header("Subtitle System")]
    [SerializeField] private SubtitleController subtitleController;

    [Header("Text Size Selection")]
    [SerializeField] private GameObject textSmallGreen;
    [SerializeField] private GameObject textMediumGreen;
    [SerializeField] private GameObject textLargeGreen;

    [Header("Mini-game Speed Selection")]
    [SerializeField] private GameObject speedSlowGreen;
    [SerializeField] private GameObject speedMediumGreen;
    [SerializeField] private GameObject speedFastGreen;

    [Header("Player Controller")]
    [SerializeField] private PlayerController playerController;

    private void Start()
    {
        // Initialize the default accessibility options.
        SetNormalContrast();
        SelectMediumText();
        SelectMediumSpeed();
    }

    // CONTRAST
        public void SetNormalContrast()
    {
        hudNormal.SetActive(true);
        hudHigh.SetActive(false);
        hudVeryHigh.SetActive(false);

        contrastNormalGreen.SetActive(true);
        contrastHighGreen.SetActive(false);
        contrastVeryHighGreen.SetActive(false);
    }

    public void SetHighContrast()
    {
        hudNormal.SetActive(false);
        hudHigh.SetActive(true);
        hudVeryHigh.SetActive(false);

        contrastNormalGreen.SetActive(false);
        contrastHighGreen.SetActive(true);
        contrastVeryHighGreen.SetActive(false);
    }

    public void SetVeryHighContrast()
    {
        hudNormal.SetActive(false);
        hudHigh.SetActive(false);
        hudVeryHigh.SetActive(true);

        contrastNormalGreen.SetActive(false);
        contrastHighGreen.SetActive(false);
        contrastVeryHighGreen.SetActive(true);
    }

    // TEXT SIZE
        public void SelectSmallText()
    {
        textSmallGreen.SetActive(true);
        textMediumGreen.SetActive(false);
        textLargeGreen.SetActive(false);

        subtitleController.SetTextSize(14);
    }

    public void SelectMediumText()
    {
        textSmallGreen.SetActive(false);
        textMediumGreen.SetActive(true);
        textLargeGreen.SetActive(false);

        subtitleController.SetTextSize(18);
    }

    public void SelectLargeText()
    {
        textSmallGreen.SetActive(false);
        textMediumGreen.SetActive(false);
        textLargeGreen.SetActive(true);

        subtitleController.SetTextSize(22);
    }

    // MINI-GAME SPEED
        public void SelectSlowSpeed()
    {
        speedSlowGreen.SetActive(true);
        speedMediumGreen.SetActive(false);
        speedFastGreen.SetActive(false);

        if (playerController != null)
        {
            playerController.SetMoveSpeed(4f);
        }
    }

    public void SelectMediumSpeed()
    {
        speedSlowGreen.SetActive(false);
        speedMediumGreen.SetActive(true);
        speedFastGreen.SetActive(false);

        if (playerController != null)
        {
            playerController.SetMoveSpeed(5f);
        }
    }

    public void SelectFastSpeed()
    {
        speedSlowGreen.SetActive(false);
        speedMediumGreen.SetActive(false);
        speedFastGreen.SetActive(true);

        if (playerController != null)
        {
            playerController.SetMoveSpeed(6f);
        }
    }
}